// Logo de Finzo para el PDF, incrustado como texto.
//
// Va incrustado y no como archivo a proposito: expo-print arma el PDF en un
// WebView aislado que no puede leer archivos del celular ni bajar nada de
// internet. Un <img src="file://..."> o una URL saldrian como recuadro roto.
//
// Son 192x192 px para un logo que se dibuja a 42: el doble largo de lo
// necesario en pantalla, porque un PDF se imprime y se hace zoom, y ahi un
// logo justo de tamano se ve pastoso. Guardar el
// icono de 1024 habria metido casi un megabyte de texto en el paquete para
// verse igual.
//
// Generado por scratchpad/nt/gen-logo.mjs a partir de assets/images/icon.png.
// Si cambia el icono de la app, hay que volver a generarlo o el PDF seguira
// llevando el cerdito viejo.
export const LOGO_DATA_URI =
  "data:image/png;base64,";
